param([Parameter(Mandatory = $true)][string]$PassportPath,[Parameter(Mandatory = $true)][ValidateRange(0,1)][double]$QualityScore,[Parameter(Mandatory = $true)][ValidateRange(0,1)][double]$SecurityScore,[Parameter(Mandatory = $true)][ValidateRange(0,1)][double]$EvidenceScore,[Parameter(Mandatory = $true)][ValidateRange(0,1)][double]$ReliabilityScore,[Parameter(Mandatory = $true)][string]$EvidenceRef,[switch]$PassThru)
$ErrorActionPreference='Stop';function Emit([object]$v,[int]$c=0){if($PassThru){$v|ConvertTo-Json -Depth 12}else{$v|Format-List};if($c-ne 0){exit $c}};try{$p=Get-Content -LiteralPath ((Resolve-Path -LiteralPath $PassportPath -ErrorAction Stop).Path)-Raw -Encoding UTF8|ConvertFrom-Json}catch{Emit ([ordered]@{status='blocked';reason='tool_passport_invalid';assessment_written=$false}) 1};if($EvidenceRef-notmatch'^(?:[a-z][a-z0-9+.-]*://|sha256:)[^\s]+$'){Emit ([ordered]@{status='blocked';reason='trust_evidence_required';assessment_written=$false}) 1};$score=[math]::Round(($QualityScore+$SecurityScore+$EvidenceScore+$ReliabilityScore)/4,4);$r=[ordered]@{schema_version=1;assessment_id='trust-'+[Guid]::NewGuid().ToString('n');passport_id=[string]$p.passport_id;quality_score=$QualityScore;security_score=$SecurityScore;evidence_score=$EvidenceScore;reliability_score=$ReliabilityScore;trust_score=$score;evidence_ref=$EvidenceRef;permission_expanded=$false;release_state_unchanged=$true;created_at=[DateTime]::UtcNow.ToString('o')};$path=[IO.Path]::ChangeExtension($PassportPath,'.trust.json');[IO.File]::WriteAllText($path,($r|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false));Emit ([ordered]@{status='assessed';trust_score=$score;assessment_path=$path;permission_expanded=$false})
